    C c;
    function setUp() public { c = new C(); }

    // Fuzz: from address, an array length hint (we will construct array of size 1), value and decimals
    function testFuzz_property(address from, uint256 v, uint8 _decimals) public {
        // Keep inputs reasonable but broad
