        // bound v so multiplication won't overflow uint (v * 10**_decimals) must fit in uint256
        v = bound(v, 0, type(uint256).max / 10);
        _decimals = uint8(bound(_decimals, 0, 77)); // 10**78 would overflow, keep safe

        // Deploy an adversarial callee that interprets parameters as (address expectedFrom, address to, uint256 value)
        // and will revert unless the first argument equals a stored expectedFrom value.
        AttackerCallee attacker = new AttackerCallee(from);

        // Prepare single-element tos array where the legitimate 'to' is some address different than 'from'
        address[] memory tos = new address[](1);
        // choose a to that is not equal to from to allow mutant swapping to fail
        address to = address(uint160(uint256(keccak256(abi.encodePacked(from, v, _decimals, block.timestamp)))));
        if (to == from) {
            // ensure different
            to = address(uint160(uint256(keccak256(abi.encodePacked(to, 1)))));
        }
        tos[0] = to;

        // Call transfer; capture whether it reverted
        bool ok;
        try c.transfer(from, address(attacker), tos, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule asserted: the reference implementation always succeeds (ok == true) for all admissible inputs
        // because it calls transferFrom(from, to, value) matching attacker expectation; the mutant that swaps
        // the first two addresses can cause the attacker to revert when it expects the first arg == from but
        // receives 'to' instead. We assert that c.transfer did not revert.
        assertTrue(ok);
    }
}

// Adversarial helper: reverts unless the first address argument equals the stored expectedFrom
contract AttackerCallee {
    address public expectedFrom;
    constructor(address _expectedFrom) {
        expectedFrom = _expectedFrom;
    }
    // We implement a function with selector matching transferFrom(address,address,uint256)
    // and revert unless the first parameter equals expectedFrom.
    function transferFrom(address a, address b, uint256 v) external returns (bool) {
        require(a == expectedFrom, "first param mismatch");
        // succeed otherwise
        return true;
    }
}

