// Adversarial callee: expects selector transferFrom(address,address,uint256) and checks args exactly
contract Enforcer {
    address public expectedFrom;
    address public expectedTo;
    uint256 public expectedValue;
    bytes4 private constant SEL = bytes4(keccak256("transferFrom(address,address,uint256)"));

    constructor(address _from, address _to, uint256 _val) {
        expectedFrom = _from;
        expectedTo = _to;
        expectedValue = _val;
    }

    fallback() external payable {
        // decode calldata: selector + encoded args
        bytes4 sel;
        // calldata layout: 4 bytes selector, then args
        assembly { sel := calldataload(0) }
        require(sel == SEL, "bad selector");
        // decode args
        (address a1, address a2, uint256 v) = abi.decode(msg.data[4:], (address, address, uint256));
        // enforce exact order and values
        require(a1 == expectedFrom, "from mismatch");
        require(a2 == expectedTo, "to mismatch");
        // value comparison is relaxed: if expectedValue==0 allow any; else require equality to make fuzzer search
        require(v == expectedValue, "value mismatch");
    }
}

