contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: from address, single to address in array, calleeExpectedFrom address, value and decimals
    function testFuzz_property(address from, address toAddr, address calleeExpectedFrom, uint256 v, uint256 _decimals) public {
        // admissible domain: to array must be non-empty; avoid extremely large decimals causing overflow in multiplication
        vm.assume(toAddr != address(0));
        vm.assume(_decimals <= 18); // keep 10**_decimals within reasonable range for fuzz
        vm.assume(v <= type(uint256).max / (10 ** _decimals == 0 ? 1 : 10 ** _decimals));

        address[] memory tos = new address[](1);
        tos[0] = toAddr;

        // Deploy an adversarial callee that only accepts transferFrom when the FIRST arg equals calleeExpectedFrom
        // i.e., it expects transferFrom(expectedFrom, allowedTo, value)
        AdversarialCallee adv = new AdversarialCallee(calleeExpectedFrom, toAddr);

        // Now call c.transfer. The correct contract will call adv.transferFrom(from, to, value)
        // which succeeds only if from == calleeExpectedFrom. The mutant swaps (to, from, value) so it will send
        // adv.transferFrom(to, from, value) and thus succeed only if to == calleeExpectedFrom.

        // We'll treat a successful overall call as ok==true, and a revert as ok==false.
        bool ok;
        try c.transfer(from, address(adv), tos, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ANY admissible inputs, the reference C will behave as if it called
        // adv.transferFrom(from,to,value). Therefore, when adv is configured to accept only when the
        // first parameter equals calleeExpectedFrom, the call succeeds iff from == calleeExpectedFrom.
        // We assert that the observed ok equals (from == calleeExpectedFrom).
        // This holds for the reference C for all admissible inputs, but the mutant (which swaps the first two args)
        // will make ok equal (to == calleeExpectedFrom) for some inputs and thus violate this assertion.
        assertTrue(ok == (from == calleeExpectedFrom));
    }
