// Adversarial callee: only accepts transferFrom when first argument equals expectedFrom and second equals allowedTo
contract AdversarialCallee {
    address public expectedFrom;
    address public allowedTo;

    constructor(address _expectedFrom, address _allowedTo) {
        expectedFrom = _expectedFrom;
        allowedTo = _allowedTo;
    }

    // mimic ERC20 transferFrom signature
    function transferFrom(address a, address b, uint256) external returns (bool) {
        // require the first argument equals expectedFrom and second equals allowedTo
        if (a != expectedFrom || b != allowedTo) revert();
        return true;
    }
}

