// Adversarial helper: accepts the low-level call only if the first decoded address argument equals `allowed`.
contract AcceptIfFirstArgMatches {
    address public allowed;
    constructor(address _allowed) { allowed = _allowed; }

    // We implement a fallback that decodes calldata for selector transferFrom(address,address,uint256)
    // and reverts unless the first address arg equals allowed.
    fallback() external payable {
        // calldata layout: 4 selector + 32 (arg0) + 32 (arg1) + 32 (arg2)
        if (msg.data.length < 4 + 32 * 3) revert();
