pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // We'll pick a fuzzed actor 'from' and fuzzed arrays of recipients encoded by a single address and length
    // The difference manifests when the callee executes code that would modify storage if called with delegatecall.
    function setUp() public { c = new C(); }

    // fuzz parameters: an address 'from' and an address 'maliciousCallee' which we will deploy as a helper
    // and a uint8 tosLen to build a non-empty recipients array, and uint v and uint8 decimals
    function testFuzz_property(address from, uint8 tosLen, uint v, uint8 decimals) public {
        // admissible domain: tosLen must be > 0 because contract requires non-empty _tos
        vm.assume(tosLen > 0);
        // bound decimals to a reasonable range to avoid overflow in test environment
        decimals = uint8(bound(uint256(decimals), 0, 18));
        // Deploy an adversarial callee that, when executed via delegatecall, will write to storage slot 0
        // (slot 0 is often used; we only observe through a public surface of C. Since C has no public
        // state variable named 'transfer', we instead observe whether calling transfer reverts or returns true.
        // The reference uses call and so executes callee in callee context; delegatecall would execute in C's context
        // and could alter C's state causing different observable behavior. We'll detect difference via success boolean.

        // Deploy the attacker helper
        MaliciousDelegateWriter mal = new MaliciousDelegateWriter();

        // Build a recipients array of length tosLen filled with the helper's address — fuzz controls length
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            tos[i] = address(mal);
        }

        // Now call c.transfer; capture whether it returns or reverts. The reference contract uses call and will invoke
        // the helper's function in the helper's context; the helper is written so that when called via delegatecall it
        // will attempt to write to storage slot 0 and then succeed. That delegatecall would succeed and can change C's
        // storage, but a normal call will not change C's storage and should succeed as well. However, if the helper's
        // code uses a storage write that under delegatecall corrupts C's layout causing a revert for some parameters,
        // the mutant (using delegatecall) may revert while the reference (using call) does not — giving a differing outcome.

        bool ok;
        try c.transfer(from, address(mal), tos, v, decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for all inputs the reference contract's transfer invocation does not revert when interacting
        // with this helper (the helper's code is benign when called normally), i.e., ok == true for the reference.
        // The mutant that uses delegatecall can cause the call to revert for some inputs; therefore we assert that
        // the call succeeded here. This single assertion is true for the reference implementation for all inputs
        // but will fail for the mutant on some inputs the fuzzer can find.
        assertTrue(ok);
    }
}

// Adversarial helper: when executed with delegatecall, this will write to storage slot 0 and then return true.
// When executed via a normal call, it writes to its own storage and returns true (no harm). If delegatecall
// changes C's storage layout in a way that triggers revert elsewhere, the mutant behavior diverges.
contract MaliciousDelegateWriter {
    // occupy a storage slot so delegatecall writing to slot 0 will hit a meaningful location
    uint256 public placeholder;

